(window.TNQ=window.TNQ||[]).push({"terms":{"사회보험":{"d":"사회적 위험을 보험 방식으로 대처해 건강과 소득을 보장하는 제도. 비용은 사용자·피용자·자영업자가 부담함이 원칙이다.","r":[]},"공공부조":{"d":"생활이 어려운 국민의 최저생활을 국가 책임으로 보장하는 제도. 비용은 수익자가 아닌 국가 등이 부담한다.","r":[]},"사회서비스":{"d":"국가·지방자치단체 및 민간부문의 도움이 필요한 사람에게 복지·보건·교육 등을 제공해 삶의 질을 높이는 제도.","r":[]},"구상권":{"d":"타인을 대신해 갚은 사람이 그 타인에게 상환을 청구하는 권리. 제3자 불법행위의 경우 급여 운영자가 행사한다.","r":[]},"소정급여일수":{"d":"하나의 수급자격으로 구직급여를 받을 수 있는 최대 일수. 피보험기간·연령·장애 여부에 따라 정해진다.","r":[]},"대기기간":{"d":"구직급여 수급자격 인정 후 실업 상태임을 확인하는 기간으로, 이 기간이 끝난 다음날부터 급여일수를 센다.","r":[]},"훈련연장급여":{"d":"직업안정기관의 장이 직업능력개발 훈련 수강을 지시한 수급자격자에게 지급하는 연장급여.","r":[]},"개별연장급여":{"d":"취업이 특히 곤란하고 생활이 어려운 수급자격자에게 대통령령으로 정한 기간 지급하는 연장급여.","r":[]},"우선지원 대상기업":{"d":"고용안정·직업능력개발 사업의 지원에서 우대받는 중소기업. 산업별 상시 사용 근로자 수 기준으로 정한다.","r":[]},"치유":{"d":"부상이나 질병이 완치되거나 치료 효과를 더 이상 기대할 수 없고 증상이 고정된 상태에 이른 것.","r":[]},"중증요양상태":{"d":"부상·질병이 치유되지 않은 채 요양 중이면서 상태의 정도가 정해진 중증 기준에 해당하는 것. 상병보상연금의 지급 요건이다.","r":[]},"진폐":{"d":"분진을 흡입하여 폐에 섬유증식성 변화가 생기는 것을 주된 증상으로 하는 직업성 질병.","r":[]},"업무상질병판정위원회":{"d":"업무와 질병 사이의 인과관계를 판정하는 근로복지공단 소속 위원회. 이 위원회 심의를 거친 결정은 재심사를 바로 청구할 수 있다.","r":[]},"상병보상연금":{"d":"요양 개시 후 일정 기간이 지나도 치유되지 않고 중증요양상태등급 기준에 해당하는 경우 휴업급여 대신 주는 연금.","r":[]},"직업재활급여":{"d":"장해급여자의 직장복귀와 재활을 돕기 위해 훈련비용, 직업훈련수당 등을 지급하는 보험급여.","r":[]},"출산 크레딧":{"d":"출산이나 입양한 자녀 수에 따라 국민연금 가입기간을 추가로 인정하는 제도입니다.","r":[]},"군복무 크레딧":{"d":"군복무 기간을 국민연금 가입기간으로 추가 인정하는 제도입니다.","r":[]},"실업 크레딧":{"d":"구직급여 수급기간을 국민연금 가입기간으로 산입하는 제도입니다.","r":[]},"반환일시금":{"d":"국민연금 가입기간이 연금 수급에 못 미치는 등의 경우 본인이나 유족이 청구해 한꺼번에 돌려받는 급여.","r":[]},"조기노령연금":{"d":"55세 이상이 소득 있는 업무를 하지 않을 때 일찍 청구해 받는 감액 연금입니다.","r":[]},"선별급여":{"d":"요양급여 중 경제성이나 치료효과성이 불확실해 본인부담률을 달리 정해 실시하는 급여.","r":[]},"보수월액":{"d":"직장가입자가 받는 보수를 기준으로 산정한 월 금액. 이에 보험료율을 곱해 보수월액보험료를 정한다.","r":[]},"하수급인":{"d":"원수급인으로부터 사업의 전부 또는 일부를 도급받아 하는 자. 도급받은 자로부터 다시 도급받은 자는 제외한다.","r":[]},"기준보수":{"d":"보수 관련 자료가 없거나 파악이 곤란할 때 고용보험위원회 심의를 거쳐 정해 보수로 삼는 금액. 시간·일·월 단위가 있다.","r":[]},"개산보험료":{"d":"보험연도 초에 그 해 근로자에게 지급할 보수총액 등을 추정해 미리 신고·납부하는 보험료.","r":[]},"사회보장수급권":{"d":"사회보장급여를 받을 수 있는 국민의 권리. 양도·담보 제공이 안 되고 법령 외에는 제한·정지될 수 없다.","r":[]},"사회보장급여":{"d":"사회보장제도에 따라 국가·지방자치단체가 국민에게 제공하는 현금, 현물, 서비스 등을 통틀어 이르는 말.","r":[]},"사회보장위원회":{"d":"사회보장 정책을 심의·조정하는 국무총리 소속 위원회. 기본계획과 재정추계 결과 등을 심의한다.","r":[]},"기본계획":{"d":"사회보장기본법에 따라 사회보장 정책의 기본방향을 정하여 수립하는 계획. 다른 계획의 기본이 된다.","r":[]},"시행계획":{"d":"기본계획을 실행하기 위해 소관 중앙행정기관이 해마다 수립하는 세부 계획. 추진 실적을 평가받는다.","r":[]},"재정추계":{"d":"사회보장제도의 안정적 운영을 위해 앞으로의 수입과 지출을 장기적으로 예측하는 작업.","r":[]},"사회보장통계":{"d":"사회보장정책의 수립·시행을 위해 작성·관리하는 사회보장 관련 통계.","r":[]},"사회보장정보시스템":{"d":"사회보장 업무를 정보화해 급여 중복·누락을 막기 위해 보건복지부장관이 운영하는 정보시스템.","r":[]},"전달체계":{"d":"사회보장급여가 서비스 제공자를 거쳐 대상자에게 전해지는 조직과 경로. 공공과 민간이 연계된다.","r":[]},"최저보장수준":{"d":"국가가 모든 국민에게 보장해야 하는 최소한의 사회보장 급여 수준. 매년 공표한다.","r":[]},"상호주의":{"d":"외국인에게 그 외국이 자국민에게 주는 것과 같은 정도의 대우를 하는 원칙.","r":[]},"자활":{"d":"스스로 생활을 꾸려 가는 것. 국민기초생활 보장법에서 근로기회를 제공해 자립을 돕는 사업과 연결된다.","r":[]},"구직급여":{"d":"고용보험의 실업급여 중 이직한 피보험자가 재취업활동을 하는 동안 소정급여일수 안에서 지급받는 급여.","r":[]},"피보험 단위기간":{"d":"구직급여 수급요건을 따질 때, 피보험기간 중 보수 지급의 기초가 된 날을 합해 계산하는 기간.","r":[]},"피보험자격":{"d":"고용보험의 적용을 받는 피보험자로서의 지위. 취득과 상실은 사업주가 신고하고 확인을 청구할 수 있다.","r":[]},"실업급여":{"d":"고용보험에서 실직자의 생활 안정과 재취업을 돕는 급여. 구직급여와 취업촉진 수당 등으로 이루어진다.","r":[]},"실업급여수급계좌":{"d":"실업급여를 받기 위해 신청인이 지정하는 금융기관 계좌. 일정 금액 이하의 예금은 압류할 수 없다.","r":[]},"취업촉진 수당":{"d":"실업급여 중 조기재취업 수당, 직업능력개발 수당, 광역 구직활동비, 이주비를 이르는 수당.","r":[]},"조기(早期)재취업 수당":{"d":"수급자격자가 소정급여일수를 남기고 일정 요건으로 재취업하거나 사업을 시작할 때 지급하는 취업촉진 수당.","r":[]},"광역 구직활동비":{"d":"구직활동을 위해 거주지 밖의 먼 지역을 방문할 때 드는 비용을 보전하는 취업촉진 수당.","r":[]},"이주비":{"d":"취업이나 직업훈련 때문에 주거를 옮겨야 할 때 이전 비용을 보전하는 취업촉진 수당.","r":[]},"직업능력개발 수당":{"d":"수급자격자가 직업안정기관의 장이 지시한 직업능력개발 훈련을 받는 동안 지급하는 취업촉진 수당.","r":[]},"연장급여":{"d":"구직급여 소정급여일수가 끝난 뒤에도 취업하지 못한 수급자격자에게 추가로 주는 급여. 훈련·개별·특별연장급여가 있다.","r":[]},"특별연장급여":{"d":"실업이 급증하는 등 특별한 경우 고용노동부장관이 기간을 정해 지급하는 연장급여.","r":[]},"실업의 인정":{"d":"수급자격자가 실업 상태에 있는지를 직업안정기관의 장이 확인하는 절차. 인정받은 날에 구직급여가 지급된다.","r":[]},"직업안정기관":{"d":"구직·구인 상담과 실업의 인정 등 고용보험 업무를 현장에서 처리하는 고용노동부 소속 기관.","r":[]},"고용유지지원금":{"d":"경영난으로 감원 대신 휴업·휴직 등 고용유지조치를 한 사업주에게 지급하는 지원금.","r":[]},"육아휴직 급여":{"d":"육아휴직을 한 피보험자에게 고용보험에서 지급하는 급여. 시작일 기준 월 통상임금을 바탕으로 정한다.","r":[]},"육아기 근로시간 단축 급여":{"d":"육아기에 소정근로시간을 줄인 피보험자에게 고용보험에서 지급하는 급여.","r":[]},"통상임금":{"d":"근로자에게 정기적·일률적으로 소정근로나 총 근로에 대해 지급하기로 정한 시간급·일급·주급·월급 금액.","r":[]},"단기예술인":{"d":"예술인 구직급여에서, 최종 이직 당시 짧은 기간 종사한 예술인을 이르며 별도 지급요건이 적용된다.","r":[]},"노무제공자":{"d":"근로자가 아니면서 사업주에게 노무를 제공하고 대가를 받는 사람. 산재보험법상 일정 직종이 보험 적용 대상이다.","r":[]},"일용근로자":{"d":"1일 단위로 근로계약을 체결해 일하는 근로자. 일정 기간 미만 고용되면 고용보험법 적용에서 제외된다.","r":[]},"임기제 공무원":{"d":"일정 기간을 정해 임용되는 공무원. 본인 의사에 따라 실업급여에 한정해 고용보험에 가입할 수 있다.","r":[]},"고용보험위원회":{"d":"고용보험에 관한 주요 사항을 심의하기 위해 고용노동부에 두는 위원회. 보험료율 결정 등을 심의한다.","r":[]},"고용보험기금":{"d":"고용보험사업에 쓰기 위해 보험료 등으로 조성하는 기금. 고용노동부장관이 관리·운용한다.","r":[]},"고용보험심사관":{"d":"실업급여 등 처분에 대한 심사청구를 심리하고 결정하는 고용노동부 소속 공무원.","r":[]},"재심사청구":{"d":"심사청구에 대한 결정에 불복해 고용보험심사위원회에 다시 판단을 구하는 절차. 시효중단에 관해 재판상 청구로 본다.","r":[]},"원처분등":{"d":"심사청구의 대상이 되는 원래의 처분. 심사청구만으로는 집행이 정지되지 않는다.","r":[]},"각하":{"d":"심사나 청구가 방식 위반 등으로 요건을 갖추지 못했을 때 내용을 따지지 않고 물리치는 결정.","r":[]},"기각":{"d":"심사나 청구의 내용을 따져 본 뒤 이유가 없다고 하여 받아들이지 않는 결정.","r":[]},"보정":{"d":"청구서의 흠을 고쳐 보충하는 것. 보정할 수 있으면 상당한 기간을 정해 요구한다.","r":[]},"평균임금":{"d":"산정 사유 발생일 이전 3개월간 근로자에게 지급된 임금 총액을 그 기간의 총일수로 나눈 금액.","r":[]},"장해급여":{"d":"업무상 부상·질병이 치유된 뒤 신체 등에 장해가 남은 근로자에게 산재보험에서 지급하는 보험급여.","r":[]},"장해보상연금":{"d":"장해등급에 따라 매년 연금으로 지급하는 장해급여. 수급권자의 신청으로 일부를 미리 받을 수 있다.","r":[]},"장해보상일시금":{"d":"장해급여를 연금 대신 한꺼번에 지급하는 방식. 외국 거주 외국인 등에게 적용된다.","r":[]},"간병급여":{"d":"요양급여를 받은 사람이 치유 후에도 상시·수시 간병이 필요할 때 지급하는 보험급여.","r":[]},"유족보상연금":{"d":"근로자 사망 시 유족에게 지급하는 연금. 자격 상실 사유가 생기면 같은 순위자나 다음 순위자에게 권리가 이전된다.","r":[]},"유족보상일시금":{"d":"유족보상연금을 받을 자격자가 없을 때 사망한 근로자의 유족에게 한꺼번에 지급하는 급여.","r":[]},"중증요양상태등급":{"d":"상병보상연금 지급 대상인 부상·질병의 중증 정도를 나눈 등급. 등급별로 지급일수가 정해진다.","r":[]},"휴업급여":{"d":"요양으로 취업하지 못한 기간에 평균임금을 기준으로 지급하는 산재보험의 보험급여.","r":[]},"요양급여":{"d":"건강보험에서 가입자 질병·부상에 대한 진찰, 검사, 약제, 수술, 간호, 치료재료 지급 등을 제공하는 급여.","r":[]},"재요양":{"d":"치유 후 부상·질병이 재발하거나 악화되어 다시 요양급여를 받는 것.","r":[]},"직장복귀지원금":{"d":"장해급여자를 복귀시켜 고용을 유지한 사업주에게 일정 기간 지급하는 지원금.","r":[]},"장의비":{"d":"근로자 사망 시 장례를 지낸 사람에게 평균임금의 일정 일수분을 지급하는 산재보험의 보험급여.","r":[]},"진폐보상연금":{"d":"진폐로 요양 중인 근로자에게 진폐장해등급별 연금과 기초연금을 합산해 지급하는 급여.","r":[]},"특수형태근로종사자":{"d":"근로자는 아니지만 특정 사업에 노무를 제공하고 대가를 받는 사람. 산재보험법이 정한 직종은 보험 적용 대상이 된다.","r":[]},"근로복지공단":{"d":"산재보험의 보험급여 지급과 심사 청구 접수 등을 맡는 기관.","r":[]},"시효":{"d":"일정 기간 권리를 행사하지 않으면 그 권리가 소멸하는 제도. 보험급여를 받을 권리마다 기간이 다르다.","r":[]},"해촉":{"d":"위촉했던 위원 등을 임기 중에 그 자리에서 물러나게 하는 것.","r":[]},"산재보험 의료기관":{"d":"산업재해보상보험의 요양급여를 제공하는 의료기관. 부당하게 진료비를 받으면 징수 및 명단 공개의 대상이 된다.","r":[]},"플랫폼 종사자":{"d":"온라인 플랫폼을 통해 노무를 제공하는 노무제공자.","r":[]},"플랫폼 운영자":{"d":"온라인 플랫폼을 이용해 플랫폼 종사자의 노무제공을 중개 또는 알선하는 것을 업으로 하는 자.","r":[]},"평균보수":{"d":"노무제공자의 보험급여 산정 기준이 되는 금액. 재해가 발생한 사업과 그 밖의 사업에서 받은 보수를 합산해 총 일수로 나눈다.","r":[]},"출퇴근 재해":{"d":"취업과 관련해 주거와 취업장소 사이를 오가다 입은 재해. 일정한 일탈·중단 사유가 있어도 재해로 보는 경우가 있다.","r":[]},"출퇴근":{"d":"취업과 관련하여 주거와 취업장소 사이의 이동 또는 한 취업장소에서 다른 취업장소로의 이동.","r":[]},"업무상의 재해":{"d":"업무상의 사유에 따른 근로자의 부상, 질병, 장해 또는 사망. 업무상 사고, 질병, 출퇴근 재해로 나뉜다.","r":[]},"장해":{"d":"업무상의 부상·질병이 치유된 뒤 정신적·육체적 훼손으로 노동능력이 상실되거나 감소된 상태.","r":[]},"유족":{"d":"사망한 사람의 배우자(사실혼 포함), 자녀, 부모, 손자녀, 조부모 또는 형제자매.","r":[]},"보험급여":{"d":"산재보험에서 업무상 재해를 입은 근로자나 그 유족에게 지급하는 요양급여, 휴업급여, 장해급여 등의 급여.","r":[]},"산재보험료율":{"d":"산재보험료를 정하는 비율. 사업 종류별로 정하며 전체 사업의 평균 산재보험료율과 비교해 상한을 둔다.","r":[]},"유사명칭의 사용 금지":{"d":"근로복지공단이 아닌 자가 근로복지공단 또는 이와 비슷한 명칭을 쓰지 못하게 한 규정. 위반하면 과태료를 부과한다.","r":[]},"일괄적용사업":{"d":"사업이 여러 곳에서 따로 이루어져도 하나의 사업으로 묶어 보험관계를 적용받는 사업.","r":[]},"보험가입자":{"d":"산재보험 또는 고용보험의 보험료 납부 의무를 지는 사업주.","r":[]},"보험관계":{"d":"사업주와 보험사업자인 근로복지공단 사이에 성립하는 보험의 법률관계. 성립일과 소멸일이 법령으로 정해진다.","r":[]},"월별보험료":{"d":"사업주가 매달 납부하는 보험료. 보험료율이 인상되면 증액 조정하고 추가분을 징수한다.","r":[]},"확정보험료":{"d":"보험연도가 끝난 뒤 실제 지급한 보수총액을 기준으로 확정하는 보험료. 개산보험료와 정산한다.","r":[]},"일할계산":{"d":"한 달의 일부 기간만 해당하는 경우 그 달의 금액을 일수에 비례해 나누어 계산하는 방법.","r":[]},"원수급인":{"d":"사업의 도급을 발주자로부터 직접 받은 자. 하수급인은 원수급인으로부터 도급받는다.","r":[]},"보험사무대행기관":{"d":"사업주를 대신해 보험 가입·신고·납부 등의 보험사무를 처리하도록 인가받은 기관.","r":[]},"소멸시효":{"d":"일정 기간 권리를 행사하지 않으면 권리가 소멸하는 제도. 독촉이나 고지 등이 있으면 중단되고 그때부터 새로 진행한다.","r":[]},"교부청구":{"d":"다른 체납처분 절차에서 이미 압류된 재산의 매각대금에서 자기 채권의 배분을 요구하는 절차.","r":[]},"결손처분":{"d":"소멸시효 완성 등으로 더 이상 징수할 수 없게 된 채권을 장부에서 정리하는 행정처분.","r":[]},"체납처분비":{"d":"체납된 금액을 강제로 징수하기 위한 절차에서 드는 비용. 징수금 반환 시 충당 순위에 든다.","r":[]},"분할 납부":{"d":"체납한 보험료 등을 승인받아 여러 차례에 나누어 내는 것. 일정 사유가 생기면 승인이 취소될 수 있다.","r":[]},"연체금":{"d":"납부기한까지 내지 않은 보험료에 대해 기한이 지난 뒤 가산하여 징수하는 금액.","r":[]},"노령연금":{"d":"국민연금 가입기간이 일정 기간 이상인 가입자가 정해진 연령이 되면 생존하는 동안 지급하는 연금.","r":[]},"유족연금":{"d":"국민연금 가입자 또는 가입자였던 자가 사망한 경우 그 유족에게 지급하는 연금.","r":[]},"장애연금":{"d":"국민연금 가입 중 생긴 질병·부상으로 장애가 남은 경우 장애등급에 따라 지급하는 연금.","r":[]},"기본연금액":{"d":"국민연금 급여액 산정의 기초가 되는 금액. 가입기간이 일정 기간을 넘으면 초과분에 따라 가산한다.","r":[]},"부양가족연금액":{"d":"수급권자가 부양하는 가족이 있을 때 연금액에 더해 주는 금액.","r":[]},"기준소득월액":{"d":"국민연금 보험료와 급여를 계산하는 기준이 되는, 가입자가 신고한 소득월액.","r":[]},"평균소득월액":{"d":"매년 사업장가입자 전원의 기준소득월액을 평균한 금액.","r":[]},"연금보험료":{"d":"국민연금 가입자가 연금 재원 마련을 위해 내는 보험료.","r":[]},"사업장가입자":{"d":"국민연금 적용 사업장에 근무하는 사용자와 근로자로서 가입한 사람.","r":[]},"지역가입자":{"d":"사업장가입자가 아닌 국민 중 가입 대상으로서 국민연금 또는 건강보험에 가입한 사람.","r":[]},"임의가입자":{"d":"국민연금 의무가입 대상이 아니지만 본인 희망으로 신청해 가입한 사람. 신청해 탈퇴할 수 있다.","r":[]},"임의계속가입자":{"d":"가입 상한 연령에 이른 가입자가 연금 수급을 위해 신청해 계속 가입하는 사람.","r":[]},"가입대상기간":{"d":"국민연금 가입 대상이 되는 기간. 유족연금 등 수급 요건에서 보험료 납부 기간과 비교하는 기준이 된다.","r":[]},"급여수급전용계좌":{"d":"급여만 입금되도록 관리하는 계좌. 입금된 급여와 그 채권은 압류할 수 없다.","r":[]},"국민연금공단":{"d":"국민연금 가입자 관리, 연금 급여 지급 및 심사 등 국민연금 사업을 수행하는 기관.","r":[]},"국민연금기금":{"d":"연금보험료와 운용 수익금 등을 재원으로 조성하는 국민연금 급여 지급용 기금.","r":[]},"국민연금기금운용위원회":{"d":"국민연금기금의 운용 지침과 계획을 심의·의결하는 위원회.","r":[]},"국민연금재심사위원회":{"d":"국민연금 심사청구 결정에 불복하는 재심사청구를 심리하는 보건복지부 소속 위원회.","r":[]},"국민연금심사위원회":{"d":"국민연금 처분에 대한 심사청구를 심의하기 위해 국민연금공단에 두는 위원회.","r":[]},"재결":{"d":"행정심판 등에서 청구에 대해 하는 판단 결정. 재심사위원회의 재결에는 행정심판법을 준용한다.","r":[]},"심사청구":{"d":"공단 등의 처분에 이의가 있을 때 처분을 한 기관에 다시 판단해 달라고 청구하는 절차.","r":[]},"이의신청":{"d":"건강보험에서 공단·심사평가원의 처분에 이의가 있을 때 그 기관에 신청하는 절차. 처분을 안 날부터 기한 내에 한다.","r":[]},"건강보험분쟁조정위원회":{"d":"이의신청 결정에 불복해 청구하는 심판청구를 심리·의결하는 위원회.","r":[]},"국민건강보험공단":{"d":"건강보험의 가입자 관리, 보험료 부과·징수, 보험급여 관리 등을 맡는 보험자.","r":[]},"건강보험심사평가원":{"d":"요양급여비용 심사와 요양급여 적정성 평가를 맡는 기관.","r":[]},"직장가입자":{"d":"건강보험에서 사업장의 근로자·사용자·공무원 등으로 가입한 사람. 보수월액을 기준으로 보험료를 낸다.","r":[]},"피부양자":{"d":"직장가입자에게 주로 생계를 의존하며 일정 요건을 갖춰 건강보험 혜택을 받는 가족. 별도 보험료는 없다.","r":[]},"소득월액":{"d":"직장가입자의 보수 외 소득을 기준으로 산정한 월 금액. 이에 따라 소득월액보험료를 부과한다.","r":[]},"재산보험료부과점수":{"d":"지역가입자의 재산을 점수로 환산한 것. 점수당 금액을 곱해 재산보험료를 정한다.","r":[]},"보수월액보험료":{"d":"직장가입자의 보수월액에 보험료율을 곱해 산정하는 보험료. 사용자와 근로자가 나누어 부담한다.","r":[]},"본인일부부담금":{"d":"요양급여를 받을 때 가입자가 요양기관에 직접 내는 비용의 일부.","r":[]},"비급여":{"d":"건강보험 요양급여 대상에서 제외되어 환자가 비용 전액을 부담하는 진료·항목.","r":[]},"요양기관":{"d":"건강보험 요양급여를 실시하는 병원, 약국 등 의료기관.","r":[]},"보험사무":{"d":"사업주가 해야 할 보험 가입 및 보험관계 변경·소멸 신고, 보험료 신고·납부 등의 사무.","r":[]}},"notes":{"180·210·240·270일":"소정급여일수는 나이와 피보험기간으로 정해지며 고령 구간의 일수가 길어 고령자 보호가 반영됩니다.","18세 미만 근로자는 사업장가입자로 보되 원하지 않으면 제외되고, 의료급여 수급자는 희망하면 사업장가입자가 되지 않을 수 있음":"18세 미만 근로자는 일단 사업장가입자로 보지만 원하지 않으면 빠질 수 있고 의료급여 수급자도 희망에 따라 빠집니다.","1개월 미만 동안 고용되는 사람(제2조)":"일용근로자는 고용 기간이 1개월 미만인 사람입니다.","1개월 소정근로시간 60시간 미만 또는 1주 15시간 미만인 근로자는 적용 제외지만 3개월 이상 계속 근로자와 일용근로자는 적용(시행령 제3조)":"월 60시간 미만 또는 주 15시간 미만 근로자는 제외되지만 3개월 이상 계속 일하거나 일용근로자면 적용됩니다.","1급은 기본연금액 전액, 2급은 1천분의 800, 3급은 1천분의 600에 부양가족연금액을 더함(제68조)":"장애연금 1~3급은 기본연금액의 전액·1천분의 800·1천분의 600에 부양가족연금액을 더합니다.","1일 평균임금의 100분의 70이고 취업하지 못한 기간이 3일 이내면 주지 않음(제52조)":"휴업급여는 평균임금의 100분의 70이며 취업하지 못한 기간이 3일 이내면 주지 않습니다.","1천분의 1천290이고 20년 초과 1년마다 1천분의 50을 더함(제51조)":"기본연금액 계수는 1천분의 1천290이며 20년을 넘는 가입기간 1년마다 1천분의 50씩 더합니다.","2024.12.20. 개정으로 재정추계 조항이 제5조 제4항에서 제30조의3으로 옮겨졌고, 주기는 격년에서 적어도 3년마다로 바뀜":"재정추계 조항이 제30조의3으로 이사했고 주기가 격년에서 적어도 3년마다로 바뀌었습니다.","2026년 9.5%(사업장가입자는 근로자·사용자 각 4.75%)에서 매년 0.5%p씩 올라 2033년부터 13%(각 6.5%)가 됨(제88조, 부칙 제4조)":"보험료율은 2026년 9.5%에서 해마다 0.5%p씩 올라 2033년부터 13%가 됩니다.","2026년 재산보험료부과점수당 금액은 211.5원(시행령 제44조)":"재산보험료부과점수당 금액은 2026년 기준 211.5원입니다.","2년 한도로 구직급여일액의 100분의 100":"훈련연장급여는 직업능력개발 훈련을 받는 동안 2년 한도로 구직급여일액의 100분의 100을 줍니다.","3년간 부정수급 2회 이상이고 합계 1억원 이상이거나 1회 2억원 이상이면 명단 공개 대상":"부정수급이 반복되거나 금액이 크면 이름을 공개하는 제재가 따릅니다.","3일 이내 요양으로 치유되면 요양급여를 지급하지 않음(제40조)":"요양기간이 3일 이내이면 요양급여를 주지 않습니다.","3회 이상 체납자가 신청하면 분할납부를 승인할 수 있음(제82조)":"3회 이상 체납한 사람이 신청하면 분할납부를 승인할 수 있습니다.","55세 이상이 소득 있는 업무에 종사하지 않으면 조기노령연금을 청구할 수 있고, 65세 전까지 지급 연기를 신청할 수 있음":"55세부터 일찍 받는 조기노령연금과 65세 전에 미루어 받는 연기 제도가 함께 있습니다.","60일 범위에서 100분의 70":"개별연장급여는 취업이 특히 어려운 사람에게 60일 범위에서 구직급여일액의 100분의 70을 줍니다.","65세 이후 새로 고용되거나 자영업을 개시한 사람에게는 실업급여·육아휴직 급여 등을 적용하지 않음(제10조 제2항)":"65세 이후 새로 일을 시작한 사람은 실업급여와 육아휴직 급여 등의 적용에서 빠집니다.","가입기간 10년 미만 1천분의 400, 10~20년 500, 20년 이상 600(제74조)":"유족연금액은 가입기간이 길수록 비율이 커져 10년 미만과 10~20년, 20년 이상이 서로 다릅니다.","가입기간 10년 이상이면 60세(특수직종 55세)부터 지급하되 지급개시 연령은 출생연도별로 65세까지 늦춰짐(제61조, 부칙)":"가입기간 10년 이상이면 60세부터 노령연금을 받되 지급개시 연령은 출생연도별로 65세까지 늦춰집니다.","가입기간은 종류가 바뀌거나 재취득해도 합산":"가입 종류가 바뀌거나 다시 가입해도 가입기간은 합산합니다.","가입자는 사업장·지역·임의·임의계속가입자(제7조)":"가입자는 사업장가입자, 지역가입자, 임의가입자, 임의계속가입자 네 종류입니다.","감액 조정 사실은 인하를 결정한 날부터 20일 이내에 알리고, 추가 납부기한은 30일 범위에서 한 번 연장할 수 있음":"보험료율 인하로 감액이 생기면 20일 안에 알리고 추가 납부는 30일 범위에서 한 번 늦출 수 있습니다.","같은 사유로 산재보험 유족급여를 받으면 2분의 1을 지급(제113조)":"같은 사유로 산재보험 유족급여를 받으면 국민연금 유족연금은 2분의 1만 지급합니다.","거짓·부정 수급은 급여액의 2배를 징수하고(제84조), 의료기관의 부당 진료비는 그 금액을 징수":"부정수급에는 급여액의 두 배를 걷는 징수금으로 제재하고 부당 진료비도 그만큼 돌려받습니다.","거짓 수급자·이를 도운 자·신청을 이유로 불이익을 준 사업주는 징역 또는 벌금, 유사명칭 사용과 진료계획 미제출은 과태료 대상":"거짓 수급이나 그를 도운 행위, 신청을 이유로 한 불이익은 형사처벌되고 유사명칭 사용과 진료계획 미제출은 과태료입니다.","거짓 인가로 취소되면 1년, 그 밖의 사유로 취소되면 6개월 동안 다시 인가받지 못함":"거짓으로 인가받아 취소되면 1년, 다른 사유로 취소되면 6개월간 다시 인가받지 못합니다.","결과는 위원회 심의 후 1개월 이내에 관계 중앙행정기관의 장에게 통보하고 공표(시행령 제16조의3)":"추계 결과는 위원회 심의 후 1개월 이내에 관계 중앙행정기관에 알리고 널리 공표합니다.","결손처분은 건강보험공단이 고용노동부장관 승인을 받아 함":"걷을 수 없는 보험료는 건강보험공단이 고용노동부장관의 승인을 받아 결손처분합니다.","결정에 불복하면 보건복지부에 둔 건강보험분쟁조정위원회(위원장 포함 60명 이내, 당연직 1명)에 심판청구하거나 행정소송을 제기할 수 있음(제88조~제90조)":"이의신청 결정에 불복하면 건강보험분쟁조정위원회에 심판청구하거나 행정소송을 제기할 수 있습니다.","결정이 있음을 안 날부터 90일 이내에 결정한 소속 기관을 거쳐 공단에 청구하고, 소속 기관은 5일 이내에 의견서를 붙여 보냄":"심사청구는 안 날부터 90일 안에 결정한 소속 기관을 거쳐 공단에 하고 그 기관은 5일 안에 의견서를 붙여 보냅니다.","결정 전에는 건강보험 요양급여를 받을 수 있음":"산재 결정 전에도 건강보험 요양급여를 받을 수 있어 치료가 끊기지 않습니다.","고용노동부에 두며 근로자·사용자·공익 대표를 같은 수로 구성하고(제8조), 각각 5명(시행령 제4조)":"산재보험및예방심의위원회는 고용노동부에 두며 근로자·사용자·공익 대표가 각 5명으로 같은 수입니다.","고용노동부에 두며 위원장(고용노동부차관) 1명을 포함한 20명 이내로 구성하고, 근로자·사용자·공익·정부 대표를 같은 수로 고용노동부장관이 임명·위촉(제7조)":"고용보험위원회는 고용노동부에 두며 노동자·사용자·공익·정부 대표가 같은 수로 20명 이내를 이룹니다.","고용노동부장관의 위탁으로 사업을 수행하고(제10조), 임원은 이사장 1명과 상임이사 4명을 포함한 15명 이내 이사와 감사 1명":"근로복지공단은 장관의 위탁으로 산재보험 사업을 수행하며 임원은 이사장 1명, 상임이사 4명 포함 이사 15명 이내와 감사 1명입니다.","고용노동부장관이 관리·운용하고 세부 사항은 국가재정법에 따르며(제79조), 한국은행에 기금계정을 둠(제82조)":"고용보험기금은 장관이 관리·운용하고 국가재정법을 따르며 한국은행에 기금계정을 둡니다.","고용된 날에 취득하고, 보험관계 성립일 전에 고용된 근로자는 보험관계가 성립한 날에 취득한 것으로 봄(제13조)":"피보험자격은 고용된 날 생기고 보험관계 성립 전에 고용된 근로자는 성립한 날에 생긴 것으로 봅니다.","고용보험료를 징수할 때는 휴직 등의 기간 중 사업주 외의 자에게서 받는 금품 중 고용노동부장관이 고시하는 금품도 보수로 봄":"고용보험료 계산에서는 휴직 중 사업주가 아닌 곳에서 받는 금품 중 장관이 고시한 것도 보수에 포함합니다.","고용보험료율은 1000분의 30 범위에서 정하고 고용보험위원회 심의를 거침(제14조)":"고용보험료율은 법정 상한이 1000분의 30이며 구체적 율은 고용보험위원회 심의를 거쳐 정합니다.","고용보험법·산재보험법을 적용받는 사업의 사업주(고용보험은 근로자도)는 당연히 보험가입자(제5조)":"두 법이 적용되는 사업의 사업주는 당연히 보험가입자이며 고용보험은 근로자도 가입자입니다.","고용보험운영전문위원회와 고용보험평가전문위원회를 두고, 5명 이내의 조사·연구위원을 둘 수 있음(시행령)":"위원회 아래에 운영과 평가를 맡는 두 전문위원회를 두며 조사·연구위원도 5명 이내로 둘 수 있습니다.","고용보험위원회 심의를 거쳐 시간·일·월 단위로 정하고 사업 종류별·지역별로 구분할 수 있음":"기준보수는 위원회 심의를 거쳐 정하고 시간·일·월 단위와 업종·지역별로 나눌 수 있습니다.","고용유지지원금은 둘 이상의 조치를 같은 날 실시하면 1일로 보고 보험연도 중 합계 180일까지 지급(시행령)":"고용유지지원금은 여러 조치를 같은 날 하면 하루로 보고 보험연도 중 합계 180일까지 지급합니다.","고용창출 지원은 실업자를 새로 고용해 근로자 수가 늘어난 경우 등이 대상":"고용창출 지원은 실업자를 새로 채용해 전체 근로자 수가 실제로 늘어난 사업주에게 비용을 지원합니다.","고의로 장애를 입으면 지급하지 않을 수 있고, 고의·중과실이나 정당한 사유 없이 요양 지시에 따르지 않아 악화시키면 지급 정지나 연금액을 변경하지 않을 수 있음(제82조)":"고의로 장애를 입거나 요양 지시를 따르지 않아 악화시키면 지급을 하지 않거나 정지할 수 있습니다.","고의·중과실 범죄행위나 고의 사고, 고의·중과실로 요양 지시를 따르지 않은 경우, 업무상 재해로 다른 법령의 보상을 받는 경우에는 급여하지 않음(제53조)":"고의·중과실 범죄, 요양 지시 불이행, 다른 법령으로 보상받는 업무상 재해는 건강보험이 급여하지 않습니다.","공공부조와 일정 소득 이하 국민의 사회서비스 비용은 국가와 지방자치단체가 전부 또는 일부를 부담하고, 부담 능력 있는 국민의 사회서비스 비용은 수익자 부담이 원칙":"공공부조와 저소득층 사회서비스는 국가와 지방자치단체가 부담하고 형편이 되는 사람의 서비스는 수익자가 부담합니다.","공단에는 민법의 재단법인 규정을 준용하고 결산은 회계연도 종료 후 2개월 내 보고":"국민연금공단은 재단법인과 비슷하게 운영되며 결산은 회계연도가 끝나고 2개월 안에 보고합니다.","공단은 60일 이내에 심사위원회 심의를 거쳐 결정하고 한 차례 20일 연장할 수 있음(제105조)":"공단은 60일 안에 심사위원회 심의로 결정하고 한 번 20일 연장할 수 있습니다.","공단은 법인이고 설립등기로 성립하며 해산은 법률로 정함(제19조)":"건강보험공단은 법인으로 설립등기로 성립하며 해산은 법률로 정합니다.","공단은 사업 실체가 없으면 보험관계를 소멸시킬 수 있음":"사업의 실체가 없는 곳은 공단이 직권으로 보험관계를 끝낼 수 있습니다.","공단의 인가를 받으며 공인노무사·세무사는 직무 2년 이상이어야 하고, 피보험자격 관리 등 신고 사무를 대행하되 확정보험료 부과는 대행 대상이 아님":"보험사무대행기관은 공단 인가를 받고 공인노무사·세무사는 직무 2년 이상이어야 하며 확정보험료 부과는 대행하지 못합니다.","공단이 아닌 자는 비슷한 명칭을 쓰지 못함(제34조)":"공단이 아닌 곳은 비슷한 이름을 쓸 수 없습니다.","공무원·군인 재해보상법, 선원법·어선원법·사립학교교직원연금법이 적용되는 사업, 가구내 고용활동, 농업·임업(벌목업 제외)·어업·수렵업 중 법인이 아닌 자의 상시 5명 미만 사업은 제외(시행령 제2조)":"공무원·군인 등 다른 법의 적용 사업과 가구 내 고용활동, 소규모 농림어업은 산재보험 적용에서 제외됩니다.","공무원·사립학교교직원연금 적용자·별정우체국 직원은 제외하고, 농업·임업·어업 중 법인이 아닌 자가 상시 4명 이하를 사용하는 사업의 근로자도 제외하되 본인이 신청하면 가입할 수 있음":"다른 연금 적용을 받는 사람과 소규모 농림어업 근로자는 제외되나 본인이 신청하면 가입할 수 있습니다.","관계 법령에서 따로 정한 경우 외에는 제한·정지될 수 없고, 제한·정지할 때도 목적에 필요한 최소한의 범위에 그쳐야 한다":"수급권 제한·정지는 법에 따로 정한 때만 가능하고 목적에 필요한 최소한에 그쳐야 합니다.","구직급여는 실업한 날 중 직업안정기관의 장에게 실업의 인정을 받은 날에 지급(제44조)":"구직급여는 실업 상태인 날 중 직업안정기관에서 실업을 인정받은 날에 지급됩니다.","구직급여는 폐업일 이전 24개월간 피보험 단위기간이 합산 1년 이상이어야 하고, 법령 위반으로 허가취소·영업정지를 받아 폐업한 경우는 제외(제69조의3)":"자영업자 구직급여는 폐업 전 24개월 중 피보험 단위기간이 1년 이상이어야 하고 법령 위반으로 폐업한 경우는 제외됩니다.","구직급여일액은 기초일액의 100분의 60, 최저구직급여일액은 최저기초일액의 100분의 80이고(제46조), 기초일액 상한은 11만3500원(시행령 제68조)":"구직급여일액은 기초일액의 100분의 60이고 최저구직급여일액은 최저기초일액의 100분의 80이며 기초일액에 상한이 있습니다.","국가는 사무 집행 비용을 일반회계에서 부담해야 하고, 보험사업 비용은 일부를 지원할 수 있음(제3조)":"사무 집행 비용은 일반회계에서 대는 것이 국가의 의무이고 보험사업 비용 지원은 재량입니다.","국가는 연금급여의 안정적·지속적 지급을 보장해야 함(제3조의2)":"국가는 연금급여가 안정적이고 계속 지급되도록 보장해야 합니다.","국가는 최저보장수준과 최저임금을 매년 공표하고, 국가와 지방자치단체는 이를 고려해 급여 수준을 결정(제10조)":"급여 수준은 매년 공표하는 최저보장수준과 최저임금을 고려해 결정합니다.","국가와 지방자치단체는 책임과 역할을 합리적으로 분담하고 매년 필요한 재원을 조달(제5조)":"국가와 지방자치단체는 책임과 역할을 합리적으로 나누고 필요한 재원은 해마다 마련해야 합니다.","국가와 지방자치단체 책임 아래 최저생활을 보장하고 자립을 지원하는 제도":"공공부조는 보험료와 무관하게 국가 책임으로 최저생활을 보장하고 자립도 지원합니다.","국내 거주 18세 이상 60세 미만 국민이 대상이고 공무원·군인·사학연금·별정우체국 적용자는 제외(제6조)":"가입 대상은 국내 거주 18세 이상 60세 미만 국민이며 공무원·군인·사학연금 등 적용자는 제외됩니다.","국내 거주 국민은 가입자나 피부양자가 되고, 의료급여 수급권자와 유공자등 의료보호대상자는 제외(제5조)":"건강보험은 국내 거주 국민 전체가 대상이고 별도 제도인 의료급여 수급자 등만 제외합니다.","국내 거주 외국인에게는 상호주의의 원칙에 따르되 관계 법령에서 정하는 바에 따름(제8조)":"국내 거주 외국인은 상호주의를 따르되 관계 법령에 정한 바에 따라 사회보장을 받습니다.","국내에 거주하게 된 날에 자격을 얻음(제8조)":"건강보험 자격은 국내에 거주하게 된 날 생깁니다.","국무총리 소속이며 위원장 1명, 부위원장 3명을 포함한 30명 이내로 구성(제20조·제21조)":"사회보장위원회는 국무총리 소속으로 위원장과 부위원장 3명을 포함해 30명 이내로 꾸려집니다.","국세·지방세·공과금 체납처분, 강제집행, 어음교환소 거래정지, 법인 해산이면 총액 500만원 이상일 때 납부기한 전에 징수할 수 있고 법인 합병은 사유가 아님(제27조의2)":"체납처분이나 법인 해산 등으로 총액 500만원 이상이면 납부기한 전에도 징수할 수 있고 법인 합병은 사유가 아닙니다.","국외 체류, 현역병 등 복무, 교도소 수용 기간에는 급여를 정지하되 복무·수용자는 요양급여를 실시(제54조)":"복무나 수용 중에는 급여를 멈추지만 이들이 병원 치료가 필요하면 요양급여는 계속 줍니다.","군복무 크레딧은 12개월까지 인정(제18조)":"군복무 크레딧은 12개월까지 가입기간으로 인정합니다.","근로계약에 따른 업무나 그에 따르는 행위 중 사고, 사업주가 제공한 시설물의 결함·관리소홀로 인한 사고, 사업주가 주관하거나 지시해 참여한 행사 중 사고, 휴게시간 중 사업주 지배관리하의 행위로 인한 사고가 업무상 사고(제37조 제1항 제1호)":"업무상 사고는 업무 중, 사업주 제공 시설 결함, 사업주 주관 행사, 휴게시간 중 사업주 지배관리 행위에서 생긴 사고입니다.","근로의 의사와 능력이 있는데도 취업하지 못한 상태":"실업은 일할 마음과 능력이 있는데도 일자리를 얻지 못한 상태를 말합니다.","근로자는 실업급여 보험료율의 2분의 1만 부담하고 고용안정·직업능력개발사업 보험료와 산재보험료는 사업주가 냄":"근로자는 실업급여 보험료의 절반만 내고 고용안정·직업능력개발 보험료와 산재보험료는 사업주가 부담합니다.","근로자를 사용하는 모든 사업에 적용(제6조)":"산재보험은 근로자를 쓰는 모든 사업에 적용됩니다.","근로자를 사용하는 모든 사업에 적용하되 총공사금액 2천만원 미만 공사, 가구 내 고용활동 등은 제외(시행령 제2조)":"고용보험은 근로자를 쓰는 모든 사업에 적용되지만 작은 공사나 가구 내 고용활동은 빠집니다.","근로자·사용자·공무원·교직원은 직장가입자이지만 1개월 미만 일용근로자, 현역병·전환복무자·군간부후보생, 보수를 받지 않는 선출직 공무원은 제외(제6조)":"근로자·사용자·공무원·교직원은 직장가입자이나 일용근로자, 현역병, 보수 없는 선출직 공무원은 제외됩니다.","급여 결정, 진료비·약제비 결정, 진료계획 변경, 일시지급, 합병증 예방관리, 부당이득 징수, 수급권 대위 결정이 심사청구 대상이고 보험료 부과는 대상이 아님(제103조)":"급여 결정 등은 심사청구 대상이지만 보험료 부과는 대상이 아닙니다.","급여는 관계 법령에 따라 신청하고, 다른 기관에 신청하면 그 기관이 정당한 기관으로 이송(제11조)":"급여를 엉뚱한 기관에 신청해도 그 기관이 정당한 기관으로 신청을 넘겨주어 신청인이 불이익을 받지 않습니다.","급여는 노령연금·장애연금·유족연금·반환일시금":"국민연금 급여는 노령연금, 장애연금, 유족연금, 반환일시금입니다.","급여수급전용계좌에 입금된 급여와 그 채권은 압류할 수 없고, 급여에는 법률이나 조례에 따라 조세·공과금을 감면":"연금이 입금된 전용 계좌의 돈은 압류할 수 없어 수급자의 생계가 보호되고 조세 감면 혜택도 있습니다.","급여 전액이 정지된 동안 시효는 진행하지 않음":"급여 전액이 정지된 동안에는 시효가 진행하지 않습니다.","기금운용계획은 기금운용위원회와 국무회의 심의 후 대통령 승인을 받음":"기금운용계획은 위원회와 국무회의 심의를 지나 대통령이 승인해야 확정되는 절차를 밟습니다.","기본계획은 다른 법령에 따른 사회보장 계획에 우선하며 그 기본이 됨(제17조)":"사회보장 기본계획은 다른 법령의 사회보장 계획보다 우선하며 그 바탕이 됩니다.","기본연금액의 1천분의 2천250을 일시보상금으로 줌":"가장 가벼운 장애 등급은 연금이 아니라 한 번에 받는 일시보상금으로 보상합니다.","내지 않으면 보건복지부장관 승인을 받아 체납처분(제81조)":"독촉에도 내지 않으면 보건복지부장관의 승인을 받아 체납처분을 합니다.","노령연금 수급권자, 가입기간 10년 이상인 자, 납부기간이 가입대상기간의 3분의 1 이상인 자, 사망일 전 5년 중 3년 이상 납부한 자(체납 3년 이상 제외), 장애 2급 이상 수급권자가 사망하면 지급(제72조)":"유족연금은 노령연금 수급권자, 가입기간 10년 이상인 자 등 다섯 경우 중 하나에서 사망하면 지급합니다.","노령연금 수급권자의 배우자로서 소득이 없는 사람은 지역가입자가 되지 않음(제9조)":"노령연금 수급권자의 소득 없는 배우자는 지역가입자가 되지 않습니다.","다른 법령으로 국가에서 상당 비용을 받으면 그 한도에서 급여하지 않음":"다른 법에서 이미 비용을 받았다면 중복을 피하려고 건강보험은 그 한도에서 급여를 하지 않습니다.","단기예술인에게만 신청일 이전 1개월 노무제공일 10일 미만 등의 요건이 더해짐":"단기예술인에게만 신청 전 1개월 동안 노무제공일이 10일 미만이라는 요건이 더 붙습니다.","도급 보수는 같은 업무·같은 보수자의 전 1개월 평균액으로 정함":"도급처럼 보수가 일정하지 않으면 같은 일을 하는 사람의 직전 1개월 평균액을 보수로 삼습니다.","독촉은 10일 이상 15일 이내 기한으로 하고, 사용자 2명 이상이나 세대 2명 이상이면 1명에게 한 독촉이 전원에게 효력이 있음":"독촉장 기한은 10일 이상 15일 이내로 정하고 공동 납부 책임이 있으면 한 사람에게 보낸 독촉이 모두에게 효력이 있습니다.","독촉장은 사업장 사용자·제2차 납부의무자에게 20일 이내, 지역가입자에게 3개월 이내에 발부(시행령 제64조)":"독촉장은 사업장 사용자·제2차 납부의무자에게 20일, 지역가입자에게 3개월 이내 기한으로 보냅니다.","매년 4월 28일은 산업재해근로자의 날":"해마다 4월 28일은 산업재해근로자의 날입니다.","매년 운용계획을 고용보험위원회와 국무회의 심의를 거쳐 대통령 승인을 받고, 운용 결과는 위원회 심의를 거쳐 공표(제81조)":"매년 운용계획은 위원회와 국무회의 심의를 거쳐 대통령 승인을 받고 운용 결과는 위원회 심의 후 공표합니다.","반환일시금은 가입기간 10년 미만인 자가 60세가 되거나, 사망해 유족연금이 지급되지 않거나, 국적 상실·국외 이주 때 청구(제77조)":"반환일시금은 가입기간 10년 미만인 사람이 60세가 되거나 유족연금이 없는 사망, 국적 상실·국외 이주 때 청구합니다.","배우자 재혼, 자녀·손자녀 파양, 자녀 25세·손자녀 19세가 되면 소멸하고, 태아가 출생해 수급권을 얻으면 부모·손자녀·조부모의 수급권은 소멸":"배우자 재혼, 파양, 자녀 25세·손자녀 19세가 되면 소멸하고 태아가 태어나 수급권을 얻으면 부모 등의 수급권은 소멸합니다.","범위는 진찰·검사, 약제·진료재료·의지, 처치·수술, 재활치료, 입원, 간호·간병, 이송이고 직장복귀지원금은 들어가지 않음":"요양급여는 진찰부터 이송까지 치료 전반을 포함하지만 직장복귀지원금은 요양급여가 아닙니다.","별정직·임기제 공무원은 본인 의사로 실업급여에 한정해 가입할 수 있음(제10조 제1항 제3호)":"임기제 공무원은 본인 의사에 따라 실업급여에 한정해 고용보험에 가입할 수 있습니다.","보건복지부장관 소속이며 요양급여 기준, 요양급여비용, 직장가입자 보험료율 등을 심의·의결(제4조)":"건강보험정책심의위원회는 보건복지부장관 소속으로 요양급여 기준, 요양급여비용, 직장가입자 보험료율 등을 심의·의결합니다.","보건복지부장관은 급여 업무의 공통 기준을 마련할 수 있고, 사회보장통계 운용지침을 매년 12월 31일까지 통보":"급여 업무의 공통 기준을 마련할 수 있고 통계 운용지침은 해마다 12월 31일까지 통보합니다.","보건복지부장관은 실시 연도 6월 30일까지 세부지침을 마련하고 10월 31일까지 추계하며 국민연금 재정전망이나 국가재정법상 장기 재정전망과 시기를 연계":"추계는 6월 30일까지 세부지침을 만들고 10월 31일까지 마치며 국민연금 재정전망 등과 시기를 맞춥니다.","보건복지부장관이 관계 중앙행정기관의 장과 협의해 5년마다 기본계획을 수립하고 사회보장위원회와 국무회의의 심의를 거쳐 확정(제16조)":"기본계획은 5년마다 세우고 사회보장위원회와 국무회의를 거쳐 확정합니다.","보수는 근로 대가로 받는 금품이며 실비변상적 금품과 퇴직금은 제외하고, 현물은 시가를 기준으로 공단이 정한 가액, 자료가 없으면 보건복지부장관 고시 금액을 보수로 봄":"보수는 근로 대가로 받는 금품이며 실비변상 성격의 금품과 퇴직금은 제외하고 현물은 시가로 평가합니다.","보수 외 소득월액보험료는 직장가입자 본인이, 지역가입자 보험료는 세대 전원이 연대해 부담":"보수 외 소득에 대한 보험료는 직장가입자가 직접 내고 지역가입자 보험료는 세대원 모두가 연대해 부담합니다.","보수월액보험료는 근로자·사업주, 공무원·국가가 각 100분의 50, 사립학교 교원은 본인 50·학교법인 30·국가 20을 부담(제76조)":"보수월액보험료는 근로자와 사업주가 반반 부담하며 사립학교 교원은 본인 50·학교법인 30·국가 20을 냅니다.","보수월액은 받는 보수를 기준으로 산정하고 상한·하한이 있음(제70조)":"보수월액은 받는 보수를 기준으로 산정하고 보험료에는 상한·하한이 있습니다.","보수총액은 매년 3월 15일까지 신고(제16조의10)":"보수총액 신고 기한은 매년 3월 15일입니다.","보험관계 성립·소멸은 그날부터 14일 이내에 신고하고, 14일 이내 끝나는 사업은 종료일 전날까지 신고(제11조)":"성립·소멸 신고는 14일 안에 하고 14일도 안 되는 사업은 종료일 전날까지 신고해야 합니다.","보험급여 결정에는 행정심판법상 행정심판을 제기할 수 없고, 심사·재심사 청구는 재판상 청구로 보며 재결은 행정심판 재결로 봄(제111조)":"산재 보험급여 결정에는 행정심판법상 행정심판을 할 수 없고 심사·재심사 청구는 재판상 청구로 봅니다.","보험급여는 지급 결정일부터 14일 이내에 지급하고(제82조), 수급권자가 사망하면 미지급 급여는 유족의 청구로 지급":"급여는 지급 결정일부터 14일 이내에 지급해야 하고 수급권자가 숨지면 남은 급여는 유족이 청구해 받습니다.","보험료는 고용보험료(고용안정·직업능력개발사업과 실업급여)와 산재보험료(제13조)":"보험료는 고용보험료와 산재보험료로 나뉘며 고용보험료에는 고용안정·직업능력개발사업과 실업급여분이 있습니다.","보험료는 근로복지공단이 매월 부과하고 국민건강보험공단이 징수하며 월별보험료는 다음 달 10일까지 냄(제16조의2·제16조의7)":"부과는 근로복지공단이, 징수는 건강보험공단이 하는 구조이며 월별보험료 납부는 다음 달 10일입니다.","보험료는 자격 취득일이 속한 달의 다음 달부터 상실일 전날이 속한 달까지 징수(제69조)":"보험료는 자격을 얻은 달의 다음 달부터 상실일 전날이 속한 달까지 부과합니다.","보험료 연체금은 납부기한 경과 후 1일마다 1천500분의 1(최대 1천분의 20)이고, 30일이 지나면 6천분의 1을 더해 최대 1천분의 50(제80조)":"납부기한 뒤 하루가 지날 때마다 연체금이 붙고 30일이 지나면 가산되며 두 구간 상한이 있습니다.","보험료율이 바뀌면 근로복지공단이 월별·개산보험료를 조정하고, 증액된 월별보험료는 건강보험공단이, 개산보험료는 근로복지공단이 징수(제18조)":"보험료율이 바뀌면 월별·개산보험료를 조정하고 증액분은 건강보험공단이, 개산보험료는 근로복지공단이 징수합니다.","보험료 징수권, 환급받을 권리, 보험급여를 받을 권리 등은 3년간 행사하지 않으면 소멸(제91조)":"보험료를 걷는 권리, 돌려받을 권리, 급여를 받을 권리는 모두 3년이 지나면 사라집니다.","보험료 징수는 건강보험공단에 위탁하며 징수 순위는 건강보험료와 같음(제98조)":"국민연금 보험료 징수는 건강보험공단에 맡기며 징수 순위는 건강보험료와 같습니다.","보험설계사, 새마을금고·신협 공제나 우체국보험 모집 전업자, 학습지 교사, 골프장 캐디, 택배·퀵서비스 기사, 대출모집인, 신용카드회원 모집인(전업), 대여제품 방문점검원, 어린이통학버스 기사 등이 해당하고, 자가 소비만 하는 방문판매원이나 직원을 고용해 배송하는 사람은 빠짐":"보험설계사, 학습지 교사, 골프장 캐디, 택배기사 등이 해당하고 자가 소비만 하는 방문판매원이나 직원을 고용한 배송자는 빠집니다.","부가가치세법상 변경 신고를 하면 보험관계 변경 신고를 한 것으로 봄":"부가가치세법에 따라 변경 신고를 했다면 보험관계 변경도 신고한 것으로 인정되어 중복 신고가 필요 없습니다.","부모 모두 가입자면 합의로 1명에게 산입하고 합의가 없으면 균등 배분":"부모 모두 가입자면 합의로 한 사람에게 산입하고 합의가 없으면 균등하게 나눕니다.","부분휴업급여는 평균임금에서 취업 임금을 뺀 금액의 100분의 80":"부분휴업급여는 일부 취업한 임금을 빼고 남은 금액의 100분의 80을 지급합니다.","비상근 근로자, 월 소정근로시간 60시간 미만 단시간근로자·시간제공무원, 소재지가 일정하지 않은 사업장의 근로자·사용자, 근로자가 없거나 비상근 근로자만 고용한 사업주도 제외(시행령 제9조)":"비상근이거나 월 60시간 미만 단시간근로자, 소재지가 일정하지 않은 사업장의 근로자·사용자도 제외됩니다.","비용 부담은 국가·지방자치단체·민간부문 간에 합리적으로 조정(제28조)":"비용 부담은 국가, 지방자치단체, 민간이 합리적으로 나누도록 조정합니다.","사망, 국적 상실 후 외국 거주, 외국인의 외국 거주 출국, 등급 변경으로 대상에서 빠지면 수급권이 소멸(제58조)":"사망, 국적 상실 후 외국 거주, 외국인의 출국, 등급 변경으로 제외되면 장해급여 수급권이 사라집니다.","사망, 재혼(사실혼 포함), 친족관계 종료, 자녀·손자녀 25세, 형제자매 19세, 국적 상실 후 외국 거주 등이면 자격을 잃고(제64조), 권리는 같은 순위자, 없으면 다음 순위자에게 넘어감":"사망, 재혼, 친족관계 종료, 자녀·손자녀 25세, 형제자매 19세 등이면 자격을 잃고 권리는 같은 순위자나 다음 순위자에게 넘어갑니다.","사망·국적상실·국외 거주는 다음 날, 피부양자가 되거나 수급권자가 된 날, 적용배제신청을 한 날에는 그날 상실(제10조)":"사망·국적상실·국외 거주는 다음 날 자격을 잃고 피부양자나 수급권자가 된 날, 적용배제신청일에는 그날 잃습니다.","사망 당시 연금 수급자격자가 없을 때 지급(제62조)":"유족보상일시금은 사망 당시 연금을 받을 자격자가 없을 때 지급합니다.","사업이 시작된 날, 하수급인은 하도급공사 착공일, 일괄적용은 처음 하는 사업이 시작된 날에 성립(제7조)":"보험관계는 사업이 시작된 날 성립하고 하수급인은 하도급공사 착공일, 일괄적용은 처음 사업이 시작된 날 성립합니다.","사업이 폐업·종료된 날의 다음 날, 해지 승인을 받은 날의 다음 날, 공단이 소멸을 결정·통지한 날의 다음 날, 임의가입 사업주가 근로자를 사용하지 않은 첫날부터 1년이 되는 날의 다음 날 소멸(제10조)":"보험관계 소멸은 폐업일의 다음 날, 해지 승인일의 다음 날 등 법이 정한 날의 다음 날이며 임의가입 사업주는 1년이 지난 다음 날 소멸합니다.","사업장가입자는 사망·국적상실·사용관계 종료·60세 도달의 다음 날에 상실하되 가입대상 제외자가 되면 그날 상실(제12조)":"사업장가입자는 사망·국적상실·사용관계 종료·60세 도달의 다음 날 자격을 잃고 가입대상 제외자가 되면 그날 잃습니다.","사업 종류 변경은 변경일 전날을 종전 사업 폐지일, 변경일을 새 사업 성립일로 봄":"사업 종류가 바뀌면 이전 사업은 변경일 전날 폐지, 새 사업은 변경일에 성립한 것으로 정리합니다.","사업주가 신고하지 않으면 근로자가 고용관계 증명서류를 내고 직접 신고할 수 있음":"사업주가 신고를 미루면 근로자가 피해를 보지 않도록 근로자가 증빙서류를 내고 직접 신고할 길이 열려 있습니다.","사업주가 제공한 교통수단 등을 이용하거나 그 밖의 통상적인 경로와 방법으로 출퇴근하다 생긴 사고":"출퇴근 재해는 사업주가 제공한 교통수단이나 통상적인 경로와 방법으로 출퇴근하다 생긴 사고입니다.","사업주는 취득·상실 사유가 발생한 달의 다음 달 15일까지 신고하고, 근로자가 그 전에 요구하면 지체 없이 신고(시행령)":"사업주는 취득·상실 사유가 생긴 달의 다음 달 15일까지 신고하고 근로자가 먼저 요구하면 지체 없이 합니다.","사업주의 구체적 지시를 위반한 행위, 사적 행위, 업무를 벗어난 행위로 인한 사고(시행령 제27조)":"사업주의 구체적 지시를 어긴 행위, 사적 행위, 업무를 벗어난 행위로 생긴 사고는 업무상 사고가 아닙니다.","사업 축소로 개산보험료가 100분의 30 이상 줄면 신청을 받아 감액할 수 있음":"사업 규모가 줄어 개산보험료가 크게 줄면 신청에 따라 감액해 주는 제도입니다.","사회보장정보시스템 전담기구는 한국사회보장정보원이고, 사회보장 교육은 매년 1회 이상 실시할 수 있음":"정보시스템 전담기구는 한국사회보장정보원이며 사회보장 교육은 해마다 1회 이상 할 수 있습니다.","사회보험 비용은 사용자·피용자·자영업자가 부담하는 것이 원칙이고 국가가 일부를 부담할 수 있음":"사회보험 비용은 보험 가입 주체들이 내는 것이 원칙이고 국가가 일부를 보탤 수 있습니다.","사회보험은 국가의 책임, 공공부조와 사회서비스는 국가와 지방자치단체의 책임으로 시행하는 것이 원칙(제25조 제5항)":"사회보험은 국가가, 공공부조와 사회서비스는 국가와 지방자치단체가 함께 시행하는 것이 원칙입니다.","사회적 위험을 보험의 방식으로 대처해 건강과 소득을 보장하는 제도":"사회보험은 위험을 보험 방식으로 나누어 건강과 소득을 보장하는 제도입니다.","산재보험료율은 평균의 20배를 넘지 못하고 전년 대비 100분의 30 범위에서 조정":"산재보험료율은 업종별로 달라 평균의 20배 상한이 있고 전년 대비 증감 폭도 제한됩니다.","상시 3명인 농업 법인처럼 법인이면 산재보험 당연가입":"법인이면 규모가 작은 농업 법인도 산재보험에 당연 가입합니다.","상임임원과 직원은 영리 업무에 종사하지 못함":"상임임원과 직원은 영리 업무에 종사할 수 없습니다.","생계를 같이 하던 배우자와 일정 나이 요건의 자녀·손자녀·부모·형제자매 등":"연금 수급자는 생계를 같이하던 배우자와 자녀 등 부양 관계에 있던 가족으로 나이 요건이 붙습니다.","생계를 유지하던 배우자(사실혼 포함)·자녀·부모·손자녀·조부모이고 형제자매는 없음":"유족은 생계를 유지하던 배우자·자녀·부모·손자녀·조부모이며 형제자매는 포함되지 않습니다.","생애주기의 기본욕구와 특수욕구를 함께 고려해 소득·서비스를 보장하는 맞춤형 제도":"평생사회안전망은 생애주기마다 다른 욕구를 함께 보아 소득과 서비스를 맞춤으로 보장합니다.","생후 18개월 내 부모가 모두 휴직하면 첫 6개월은 통상임금 100%를 주며 상한은 250만원에서 달마다 올라 6개월째 450만원(제95조의3)":"부모가 모두 육아휴직을 하면 첫 6개월은 통상임금 100%를 주고 상한이 달마다 올라 6개월째 450만원입니다.","서류 위조·변조로 거짓 청구해 처분받은 요양기관은 거짓 청구액이 1천500만원 이상이거나 총액의 100분의 20 이상이면 위반사실을 공표할 수 있음(제100조)":"거짓 청구로 처분받은 요양기관은 청구액이나 비율이 기준을 넘으면 위반사실이 공표될 수 있습니다.","섬·벽지·농어촌 거주자, 65세 이상, 등록 장애인, 일정 국가유공자, 휴직기간 1개월 이상인 직장가입자 등은 보험료를 경감할 수 있음(제75조)":"섬·벽지·농어촌 거주자, 65세 이상, 장애인, 국가유공자 등은 보험료를 경감할 수 있습니다.","소득세법상 근로소득에서 대통령령으로 정한 금품을 뺀 금액(제2조)":"보수는 소득세법상 근로소득에서 대통령령이 정한 금품을 뺀 금액입니다.","수급권은 관계 법령에 따라 양도·담보 제공을 할 수 없고 압류할 수 없다":"수급권은 양도하거나 담보로 제공할 수 없고 압류도 금지되어 수급자 본인에게 남습니다.","수급기간은 이직일 다음 날부터 12개월이며 임신·출산·육아 등으로 취업할 수 없으면 최대 4년까지 늘어남(제48조)":"수급기간은 이직 다음 날부터 12개월이며 임신·출산·육아 등으로 취업이 어려우면 최대 4년까지 늘어납니다.","시행계획은 매년 수립하며 평가지침은 매년 1월 31일까지 통보하고 전년도 추진실적 평가 결과는 3월 31일까지 제출(시행령)":"시행계획은 해마다 세우고 평가지침 통보일과 추진실적 평가 결과 제출일이 정해져 있습니다.","시효는 3년이지만 장해·유족급여, 장례비, 진폐보상연금·진폐유족연금은 5년(제112조)":"권리 소멸 시효가 일반 급여는 3년이지만 장해·유족처럼 오래 걸리는 급여는 5년으로 더 깁니다.","신고 의무 위반과 이직확인서 거짓 작성은 과태료, 거짓으로 급여를 받으면 징역 또는 벌금 대상":"신고 의무 위반과 거짓 이직확인서 작성은 과태료이고 거짓으로 급여를 받으면 형사처벌됩니다.","신청기간 연장 사유는 천재지변, 본인·배우자의 질병·부상, 본인·배우자의 직계존비속 질병·부상, 병역 의무복무, 구속·형 집행이고 형제자매는 해당하지 않음":"신청기간 연장 사유는 천재지변, 본인·배우자나 그 직계존비속의 질병·부상, 병역, 구속 등이고 형제자매는 해당하지 않습니다.","실업급여 1천분의 18, 고용안정·직업능력개발은 150명 미만 1만분의 25, 150명 이상 우선지원대상기업 45, 150명~1천명 미만 65, 1천명 이상과 국가·지자체 사업 85(시행령 제12조)":"실업급여 보험료율은 1천분의 18이고 고용안정·직업능력개발은 기업 규모에 따라 1만분의 25부터 85까지 차등합니다.","실업급여는 구직급여와 취업촉진 수당이고, 취업촉진 수당은 조기재취업 수당·직업능력개발 수당·광역 구직활동비·이주비(제37조)":"실업급여는 구직급여와 취업촉진 수당으로 나뉘고 취업촉진 수당에는 네 가지가 있습니다.","실업급여 받을 권리는 양도·압류·담보 제공이 금지되고, 실업급여수급계좌에 입금된 금액 전액 이하의 채권은 압류할 수 없음(제38조)":"실업급여는 양도·압류·담보가 금지되고 수급계좌에 들어온 금액 전액 이하의 채권은 압류할 수 없습니다.","실업급여에는 공과금을 부과하지 않음":"실업급여에는 조세 같은 공과금을 부과하지 않아 수급자가 실제로 받는 금액이 줄지 않습니다.","실업신고일부터 7일은 대기기간이고(제49조), 소정급여일수는 대기기간이 끝난 다음 날부터 셈":"신고 후 7일은 대기기간으로 급여를 주지 않고 소정급여일수는 대기기간 다음 날부터 셉니다.","실업 크레딧은 구직급여 수급기간을 1년 한도로 산입(제19조의2)":"실업 크레딧은 구직급여 수급기간을 1년 한도로 가입기간에 산입합니다.","심사 결과 장애등급에 해당하지 않으면 수급권이 소멸":"심사 결과 장애등급에 해당하지 않으면 장애연금 수급권이 사라집니다.","심사 결정이 있음을 안 날부터 90일 이내에 고용보험심사위원회에 재심사를 청구하고, 상대방은 원처분을 한 직업안정기관의 장 또는 근로복지공단 · 심사위원회는 노사 대표 각 1명 이상을 포함한 15명 이내, 그중 2명은 상임위원(제99조) · 심리 기일 3일 전까지 알리며, 심리는 공개가 원칙이고 당사자가 신청하면 비공개로 할 수 있음":"심사 결정에 불복하면 안 날부터 90일 안에 고용보험심사위원회에 재심사를 청구합니다.","심사관은 30일 이내에 결정하고 한 차례 10일 연장할 수 있음 · 심사청구는 집행을 정지시키지 않지만 중대한 위해를 피할 긴급한 필요가 있으면 심사관이 직권으로 정지할 수 있음(제93조) · 결정은 정본을 보낸 날부터 효력이 생기고, 보정할 수 없는 방식 위반은 결정으로 각하":"심사관은 30일 안에 결정하되 한 번 10일 연장할 수 있고 심사청구는 집행을 멈추지 않지만 긴급하면 직권 정지가 가능합니다.","심사·재심사 청구는 시효중단에 관해 재판상 청구로 보고, 재결은 행정소송법상 행정심판 재결로 봄(제104조) · 대리인은 배우자·직계존비속·형제자매, 법인의 임직원, 변호사·공인노무사, 심사위원회 허가를 받은 자(제88조)":"심사와 재심사 청구는 시효중단에서 재판상 청구로 보고 재결은 행정심판 재결과 같은 효력이며 대리인 범위도 법에 정해져 있습니다.","심사청구는 결정 전까지 문서로 취하할 수 있음":"심사청구는 결정이 나기 전이라면 본인이 문서로 거두어들일 수 있습니다.","업무상 사유에 따른 근로자의 부상·질병·장해·사망(제5조)":"업무상 재해는 업무상 사유로 근로자가 부상·질병·장해·사망을 입는 것입니다.","업무와 재해 사이에 상당인과관계가 있어야 함":"업무상 재해가 되려면 업무와 재해 사이에 상당인과관계가 있어야 합니다.","연금은 신청하면 최초 1년분 또는 2년분(완전 상실 등급은 1~4년분)의 2분의 1을 미리 지급하고 100분의 5 범위에서 이자를 공제":"연금은 신청하면 최초 1년분 또는 2년분의 2분의 1을 미리 받고 이자를 공제합니다.","연장급여는 구직급여 지급이 끝난 뒤 지급하고, 수급기간은 연장일수만큼 늘어남":"연장급여는 구직급여가 끝난 뒤에 주고 수급기간도 연장일수만큼 늘어납니다.","연체금은 1일마다 1천500분의 1(최대 1천분의 20), 30일이 지나면 6천분의 1을 더해 최대 1천분의 50(제97조)":"연체금은 하루 단위로 쌓이다가 30일이 지나면 추가분이 붙고 두 단계 모두 상한이 있습니다.","예외: 일상생활 용품 구입, 직업능력 개발 교육, 선거권 행사, 아동·장애인을 보육·교육기관에 데려다주거나 데려오는 행위, 질병 치료·예방 진료 등 일상생활에 필요한 행위(시행령 제35조)":"출퇴근 중 일상생활에 필요한 최소한의 행위로 경로를 벗어나거나 중단해도 업무상 재해로 인정되는 예외가 있습니다.","요양급여 산정기준, 산재보험료율 결정, 기금 운용계획, 산업재해 예방계획이 심의사항":"위원회는 요양급여 산정기준, 보험료율, 기금 운용계획, 재해 예방계획을 심의합니다.","요양기관은 정해진 항목 외에 입원보증금 등 다른 명목의 비용을 청구할 수 없음":"입원 때 보증금 같은 항목은 법에 없으므로 요양기관이 환자에게 요구할 수 없습니다.","요양 시작 후 2년이 지난 뒤 치유되지 않았고 중증요양상태등급에 해당하며 요양으로 취업하지 못했을 때 휴업급여 대신 지급(제66조)":"상병보상연금은 요양 시작 2년이 지나도 치유되지 않고 중증요양상태등급에 해당할 때 휴업급여 대신 지급합니다.","요양·휴업·장해·간병·유족급여, 상병보상연금, 장례비, 직업재활급여가 있음(제36조)":"산재보험 급여에는 요양, 휴업, 장해, 간병, 유족급여와 상병보상연금, 장례비, 직업재활급여가 있습니다.","용도는 고용안정·직업능력개발 경비, 실업급여, 국민연금 보험료 지원, 육아휴직·출산전후휴가 급여, 보험료 반환, 일시 차입금 상환, 업무 대행자 출연금이고 건강보험료 지원은 없음(제80조)":"기금의 용도는 고용안정·직업능력개발, 실업급여, 국민연금 보험료 지원 등이고 건강보험료 지원은 없습니다.","우선지원 대상기업은 제조업 500명 이하, 광업·건설업·운수창고업·정보통신업·보건업 등 300명 이하, 도소매·숙박음식·금융보험업 등 200명 이하, 그 밖의 업종 100명 이하(시행령 별표 1)":"우선지원 대상기업은 업종별로 상시 근로자 수 기준이 다르게 정해져 있어 제조업이 가장 큽니다.","운영원칙은 보편성(모든 국민 적용), 형평성, 민주성, 연계성·전문성(제25조)":"사회보장 운영원칙은 모든 국민에게 적용하는 보편성, 형평성, 민주성, 연계성·전문성입니다.","운용은 금융기관·재정자금 예탁, 국가·금융기관 발행·보증 유가증권 매입 등으로 함":"기금은 금융기관·재정자금에 맡기거나 국가·금융기관이 발행하거나 보증한 유가증권을 사서 운용합니다.","원수급인으로부터 사업의 전부나 일부를 도급받은 자와 그 자로부터 다시 도급받은 자를 모두 포함":"하수급인은 원수급인에게서 일을 도급받은 자뿐 아니라 그 자에게서 다시 도급받은 자도 모두 포함합니다.","월별보험료 고지, 반환 청구, 통지·독촉, 교부청구·압류가 중단사유이고, 각각 고지한 납부기한, 독촉 납부기한, 교부청구 기간이 지난 때부터 새로 진행(제42조)":"고지, 청구, 독촉, 교부청구·압류는 시효를 중단시키며 각 기한이 지난 때부터 시효가 새로 시작됩니다.","월 중간에 전근하거나 출산전후휴가가 끝나면 그 다음 달부터 새로 산정하고 일할계산은 하지 않음(제16조의4)":"월 중간에 일이 바뀌어도 그달은 일할계산하지 않고 그 다음 달부터 새 기준으로 산정합니다.","월 통상임금 기준으로 1~3개월은 100%(상한 250만원), 4~6개월은 100%(상한 200만원), 7개월째부터 80%(상한 160만원)이고 하한은 70만원(시행령 제95조)":"육아휴직 급여는 통상임금의 100%로 시작해 기간이 지나면 낮아지고 상한과 하한액이 정해져 있습니다.","위원 임기는 2년이지만 공무원인 위원은 재임기간, 보궐위원은 전임자의 남은 기간":"위원 임기는 일반적으로 2년이나 공무원 위원은 그 자리에 있는 동안만 위원이고 보궐위원은 남은 기간만 이어받습니다.","위원 임기는 3년이고 연임할 수 있으며 보궐위원은 전임자의 남은 기간":"위원은 3년 임기에 연임할 수 있으나 중간에 들어온 보궐위원은 남은 기간만 일합니다.","위원장은 국무총리, 부위원장은 교육부장관·보건복지부장관·기획예산처장관(2025.10.1. 개정)":"위원장은 국무총리이고 부위원장은 교육부·보건복지부·기획예산처 장관이 맡는 구성입니다.","위원장이 직무를 못 하면 위원장이 미리 정한 부위원장 순으로 대행":"위원장이 직무를 못 하면 미리 지정한 순서에 따라 부위원장이 직무를 대신합니다.","유족은 배우자(사실혼 포함)·자녀·부모·손자녀·조부모·형제자매이고, 출퇴근은 주거와 취업장소 사이 또는 취업장소 사이의 이동":"유족은 사실혼 배우자를 포함한 가족 범위이고 출퇴근은 주거와 취업장소 사이 또는 취업장소 사이의 이동입니다.","유해 인자 노출, 업무상 부상이 원인인 질병, 직장 내 괴롭힘·고객 폭언 등으로 인한 정신적 스트레스 질병이 업무상 질병":"업무상 질병은 유해 인자 노출, 업무상 부상, 직장 내 괴롭힘·고객 폭언 등 정신적 스트레스로 생긴 질병입니다.","육아휴직을 30일 이상 부여받고 휴직 시작 전 피보험 단위기간이 180일 이상이어야 하며 휴직 시작 후 1개월부터 종료 후 12개월 이내에 신청(제70조)":"육아휴직 급여 신청에는 휴직 기간과 가입 기간 요건이 있고 신청 시기도 정해져 있습니다.","이름·소재지 등 변경과 건설사업 기간 변경은 그날부터 14일 이내(제12조)":"이름·소재지 등 변경과 건설사업 기간 변경도 그날부터 14일 안에 신고합니다.","이주비는 1년 이상 근로계약기간으로 취업하는 경우 등에 지급":"이주비는 취업을 위해 이사하는 경우에 주며 근로계약기간이 1년 이상인 취업 등이 조건입니다.","이직·사망은 그 다음 날, 적용 제외 근로자가 되면 그날, 보험관계가 소멸하면 소멸한 날에 상실(제14조)":"이직·사망은 다음 날, 적용 제외가 되면 그날, 보험관계 소멸은 소멸한 날에 자격이 사라집니다.","이직일 이전 18개월(기준기간) 동안 피보험 단위기간이 합산 180일 이상이고, 근로 의사와 능력이 있는데도 취업하지 못했으며 이직사유가 수급자격 제한 사유가 아니고, 재취업 노력을 해야 함(제40조)":"구직급여는 이직 전 18개월 중 피보험 단위기간이 180일 이상이고 일할 의사·능력이 있으나 취업하지 못하고 재취업 노력을 해야 받습니다.","이직일 이전 24개월 동안 피보험 단위기간 9개월 이상, 그중 3개월 이상 예술인 피보험자격을 유지해야 함(제77조의3)":"예술인은 이직 전 24개월 중 피보험 단위기간이 9개월 이상이고 그중 3개월 이상 예술인 자격을 유지해야 합니다.","이직일 전 1년 이내에 2개월 이상 임금체불이 있는 경우가 정당한 이직 사유이고 1개월 체불로는 해당하지 않음(시행규칙 별표 2)":"임금체불이 2개월 이상 있었다면 정당한 이직 사유이고 1개월 체불은 해당하지 않습니다.","인정 여부는 공단 소속 기관에 둔 업무상질병판정위원회가 심의하고(제38조), 위원장 1명 포함 180명 이내로 구성(시행규칙)":"업무상 질병 인정 여부는 공단 소속 기관의 업무상질병판정위원회가 심의하며 위원장 포함 180명 이내입니다.","일괄적용 해지는 다음 보험연도 시작 7일 전까지 신청하고, 일괄적용관계 소멸은 소멸한 날부터 14일 이내에 신고":"일괄적용을 풀려면 다음 보험연도 시작 7일 전까지 신청해야 하고 관계 소멸은 그날부터 14일 안에 신고합니다.","일시금 순위는 생계를 같이 하던 배우자·자녀·부모·손자녀·조부모가 먼저(제65조)":"일시금은 생계를 같이한 가족을 앞 순위로 두어 실제로 부양받던 사람을 먼저 보호합니다.","일정 기간 이상 체납하면 완납할 때까지 가입자와 피부양자 모두에게 급여를 하지 않을 수 있음":"오래 체납하면 본인뿐 아니라 피부양자까지 완납 전에는 급여를 받지 못하게 할 수 있습니다.","임신 중 업무상 사고 등으로 출산한 자녀의 장해 등은 업무상 재해로 보고, 건강손상자녀의 급여는 요양·장해·간병급여, 장례비, 직업재활급여이며 장해등급 판정은 18세 이후에 함":"임신 중 업무상 사고로 출산한 자녀의 장해도 업무상 재해로 보며 이 자녀의 장해등급 판정은 18세 이후에 합니다.","임신·출산 진료비, 장제비, 상병수당(제50조)":"부가급여는 임신·출산 진료비, 장제비, 상병수당입니다.","임용된 날부터 3개월 이내에 직접 신청할 수 있고, 다른 임기제 공무원으로 계속 임용되면 별도 신청 없이 자격이 유지됨":"임용 후 3개월 안에 직접 신청해야 하며 다른 임기제로 이어서 임용되면 별도 신청 없이 가입이 유지됩니다.","임원은 이사장 1명, 이사 14명, 감사 1명이고 이사회 정기회의는 매년 2회":"건강보험공단의 임원 구성은 이사장과 이사, 감사로 이루어지고 이사회는 정기회의를 해마다 연 2회 엽니다.","임의가입자는 6개월 이상 체납하면 자격을 잃음":"임의가입자는 스스로 가입한 사람이라 보험료를 반년 이상 내지 않으면 가입 자격을 잃습니다.","임의가입자와 임의계속가입자는 가입 신청이 수리된 날에 취득하고, 임의가입자는 신청해 탈퇴할 수 있음(제10조)":"임의가입자와 임의계속가입자는 가입 신청이 수리된 날 자격을 얻고 임의가입자는 신청해 탈퇴할 수 있습니다.","임의가입한 고용보험계약을 해지할 때도 공단 승인과 근로자 과반수 동의가 필요":"임의가입한 계약을 끊을 때도 가입 때처럼 공단 승인과 근로자 과반수 동의가 필요합니다.","임의계속가입자는 65세가 될 때까지 신청해 가입(제13조)":"임의계속가입자는 65세가 될 때까지 신청해서 가입할 수 있습니다.","자격·보험료·보험급여 처분은 공단에, 요양급여비용과 적정성 평가 처분은 심사평가원에 이의신청(제87조)":"이의신청 기관은 처분 종류에 따라 갈려 자격·보험료·급여는 공단, 비용·평가 처분은 심사평가원입니다.","자금 부족 시 기금 부담으로 차입하고(제86조), 결산상 손실금은 적립금으로 보전할 수 있음":"자금이 부족하면 기금의 부담으로 돈을 빌리고 결산상 손실은 적립금으로 메울 수 있습니다.","자녀 2명 이하는 1명마다 12개월, 3명 이상은 24개월에 셋째부터 1명마다 18개월을 더하고 종전 50개월 상한은 없어짐(제19조)":"자녀 수에 따라 추가 인정 개월 수가 달라지고 이전에 있던 상한이 없어졌습니다.","자녀가 입양되면 지급을 정지하고 파양되면 본인 신청으로 해제":"자녀가 입양되면 친부모에 대한 지급을 멈추고 파양되면 신청에 따라 다시 지급합니다.","자영업자가 6개월간 보험료를 내지 않으면 마지막으로 낸 보험료에 해당하는 피보험기간의 다음 날 소멸":"자영업자가 반년 동안 보험료를 내지 않으면 마지막으로 낸 보험료 기간의 다음 날 보험관계가 소멸합니다.","자영업자는 근로자가 없거나 50명 미만이면 공단 승인으로 고용보험에 가입하고, 50명 이상이 되어도 원하면 계속 가입한 것으로 봄(제49조의2)":"자영업자는 근로자 50명 미만이면 가입할 수 있고 가입 후 50명을 넘어도 원하면 계속 가입한 것으로 봅니다.","자영업자 실업급여 보험료율은 1천분의 20":"자영업자는 사업주와 근로자 구분이 없어 자기 몫의 실업급여 보험료율이 따로 정해져 있습니다.","자영업자인 피보험자는 취득·상실 신고를 하지 않음":"자영업자 피보험자는 사업주와 근로자 관계가 없어 취득·상실 신고 대상이 아닙니다.","잘못 낸 금액은 체납처분비부터 충당(제23조)":"잘못 낸 보험료는 체납처분비부터 먼저 충당합니다.","장애인은 나이와 관계없이 50세 이상 기준을 적용":"장애인은 나이와 상관없이 50세 이상 기준을 적용받아 더 긴 급여일수를 받습니다.","장해급여자 중 훈련대상자의 직업훈련비용과 직업훈련수당, 직장복귀지원금, 직장적응훈련비, 재활운동비":"직업재활급여는 직업훈련비용·훈련수당, 직장복귀지원금, 직장적응훈련비, 재활운동비로 이뤄집니다.","재심사는 결정을 안 날부터 90일 이내에 고용노동부 재심사위원회에 청구하며 위원회는 위원장 1명 포함 90명 이내":"심사에 이어지는 두 번째 단계로 고용노동부의 재심사위원회에 90일 안에 청구하며 이 위원회의 규모는 90명 이내입니다.","재요양 중에도 연금은 정지하지 않음":"재요양을 받는 중에도 장해연금은 멈추지 않고 계속 지급합니다.","재적 과반수 출석, 출석 과반수 찬성으로 의결":"위원회는 재적 과반수 출석에 출석 과반수 찬성으로 의결합니다.","저소득 근로자는 1일 휴업급여가 최저 보상기준 금액의 100분의 80 이하이면 평균임금의 100분의 90을 지급하되 최저 보상기준 금액의 100분의 80을 넘지 않음(제54조)":"저소득 근로자는 휴업급여가 최저 보상기준 금액의 100분의 80 이하이면 평균임금의 100분의 90을 받되 그 100분의 80을 넘지 못합니다.","적용되지 않는 사업의 사업주는 고용보험은 근로자 과반수 동의를 받아 공단 승인으로, 산재보험은 공단 승인으로 가입할 수 있음":"적용 대상이 아닌 사업의 사업주는 고용보험은 근로자 과반수 동의로, 산재보험은 공단 승인으로 가입할 수 있습니다.","전쟁·사변, 화재 등 재해, 폐업, 정관에서 정한 소액이면 연체금을 징수하지 않을 수 있음":"전쟁·재해, 폐업, 소액 등의 사정이 있으면 연체금을 징수하지 않을 수 있습니다.","정년 도래·계약기간 만료, 성희롱 피해, 장애·노조활동 등을 이유로 한 차별, 도산·폐업 확실이나 대량 감원 예정, 동거 친족 간호로 30일 이상 필요한데 휴가가 허용되지 않은 경우도 정당한 사유":"정년, 계약만료, 성희롱 피해, 차별, 도산 예정, 가족 간호 불허 등도 스스로 그만둬도 급여를 받을 수 있는 정당한 사유입니다.","정당한 권한 있는 기관에 서면으로 통지해 포기할 수 있고 포기는 취소할 수 있으나, 남에게 피해를 주거나 법령에 위반되면 포기할 수 없다":"수급권은 서면으로 포기할 수 있고 취소도 되지만 타인에게 피해를 주거나 법에 어긋나면 포기할 수 없습니다.","제3자의 불법행위로 수급권을 갖게 되면 제도 운영자는 가해자에게 구상권을 행사할 수 있음(제15조)":"제삼자의 불법행위로 수급권이 생기면 제도 운영자는 가해자에게 지급한 만큼 구상할 수 있습니다.","제3자의 행위로 재해가 나면 지체 없이 신고하고, 공단은 급여액 한도에서 손해배상청구권을 대위(제87조)":"제삼자의 행위로 재해가 나면 공단은 지급한 급여액 한도에서 가해자에게 손해배상청구권을 대위합니다.","제도를 신설·변경할 때는 급여가 중복·누락되지 않도록 사전 검토하고 협력(제26조)":"새 제도를 만들거나 바꿀 때는 급여가 겹치거나 빠지지 않게 미리 따지고 협력해야 합니다.","중대한 귀책사유로 해고되거나 정당한 사유 없이 자기 사정으로 이직하면 수급자격이 없음(제58조)":"중대한 잘못으로 해고되거나 정당한 이유 없이 스스로 그만두면 구직급여 수급자격이 없습니다.","중증요양상태 3급은 평균임금 257일분":"중증요양상태 3급의 상병보상연금은 평균임금 257일분입니다.","지역가입자가 사업장가입자 자격을 취득하면 그날 상실":"지역가입자가 사업장가입자 자격을 얻으면 그날 지역가입자 자격을 잃습니다.","지역가입자가 사용자·근로자가 된 날, 직장가입자가 다른 사업장으로 옮긴 날, 지역가입자가 다른 세대로 전입한 날에 변동되고, 사용관계가 끝나면 그 다음 날 변동됨(제9조)":"가입 종류가 바뀌는 사유는 사용자·근로자가 된 날, 다른 사업장으로 옮긴 날, 다른 세대로 전입한 날이고 사용관계가 끝나면 다음 날 변동됩니다.","직업훈련비용은 12개월 이내 훈련에 대해 고시 범위의 실비이고, 직업훈련수당 1일 지급액은 최저임금액":"훈련비용은 실제 쓴 비용을 고시 범위에서 대고 훈련 중 생활비는 최저임금 수준의 일당으로 보충합니다.","직장가입자(나이 무관), 세대주인 지역가입자, 20세 이상 지역가입자와 피부양자(제52조)":"일반건강검진은 직장가입자 전원, 세대주인 지역가입자, 20세 이상 지역가입자와 피부양자가 대상입니다.","직장가입자 보험료율은 1천분의 80 범위에서 정하고 2026년은 1만분의 719이며, 국외 근무 직장가입자는 그 100분의 50(제73조)":"직장가입자 보험료율은 법정 상한 범위에서 해마다 정해지고 2026년 수치가 따로 있으며 국외 근무자는 절반입니다.","직장복귀지원금은 12개월 이내, 직장적응훈련비와 재활운동비는 3개월 이내로 지급(제75조)":"복귀 후 적응 지원은 지원금 12개월, 적응훈련비와 운동비 3개월로 기간이 나뉩니다.","진찰·검사, 약제·치료재료 지급, 처치·수술, 예방·재활, 입원, 간호, 이송(제41조)":"요양급여는 진찰·검사, 약제·치료재료, 처치·수술, 예방·재활, 입원, 간호, 이송입니다.","진폐는 분진 흡입으로 폐에 생기는 섬유증식성 변화가 주된 증상인 질병":"진폐는 분진을 들이마셔 폐에 섬유증식성 변화가 생기는 직업병입니다.","진폐는 요양·간병급여, 장례비, 직업재활급여, 진폐보상연금, 진폐유족연금이고 휴업·장해급여는 없음":"진폐 환자에게는 진폐 전용 연금이 따로 있고 대신 휴업급여나 장해급여는 주지 않는 점이 일반 산재와 다릅니다.","진폐는 판정위원회 심의 대상에서 제외":"진폐는 별도 절차가 있어 판정위원회 심의 대상에서 빠집니다.","질병 등으로 출석하지 못한 기간이 계속 7일 미만이면 증명서로 실업 인정을 받음":"아파서 실업 인정 출석을 못 해도 연속 7일 미만이면 증명서를 내면 인정받아 급여가 끊기지 않습니다.","징수 권리는 3년, 급여·과오납금 반환·환수금 환수 권리는 5년, 60세 도달로 생긴 반환일시금 권리는 10년(제115조)":"국민연금은 권리별로 시효가 3년, 5년, 10년으로 나뉘어 있어 어떤 권리인지 구분해야 합니다.","징수·반환 권리는 3년이고 이 법에 없으면 민법에 따름(제41조)":"징수·반환 권리는 3년이고 이 법에 없는 사항은 민법을 따릅니다.","징수법상 보험료율 결정, 보험사업 평가, 기금운용 계획이 심의사항":"위원회는 보험료율 결정, 보험사업 평가, 기금운용 계획을 심의합니다.","처분이 있음을 안 날부터 90일, 있은 날부터 180일 이내에 문서로 함":"이의신청은 안 날부터 90일, 처분일부터 180일 안에 문서로 해야 합니다.","처분이 있음을 안 날부터 90일, 처분이 있은 날부터 180일 이내에 문서로 심사청구하고, 결정통지를 받은 날부터 90일 이내에 보건복지부의 재심사위원회(20명 이내)에 재심사를 청구(제108조~제111조)":"심사청구는 안 날부터 90일, 처분일부터 180일 안에 문서로 하고 결정통지를 받은 날부터 90일 안에 재심사를 청구합니다.","천재지변 등 특수 사유가 있으면 보험료를 100분의 30 경감":"천재지변처럼 특수한 사정이 있으면 보험료를 일정 비율만큼 깎아 줍니다.","최우선 순위자만 받으며 그가 사망해도 다음 순위로 넘어가지 않음":"유족연금은 최우선 순위자만 받고 그가 사망해도 다음 순위로 권리가 넘어가지 않습니다.","출산·양육·실업·노령·장애·질병·빈곤·사망 등 사회적 위험에서 국민을 보호하는 사회보험·공공부조·사회서비스를 말한다(제3조)":"사회보장은 여러 사회적 위험에서 국민을 지키는 사회보험·공공부조·사회서비스를 아우르는 개념입니다.","출산 크레딧은 2026년 개정으로 첫째 자녀부터 인정":"출산 크레딧은 2026년 개정으로 첫째부터 인정되어 지원 범위가 넓어졌습니다.","치유는 완치되거나 치료 효과를 더 기대할 수 없고 증상이 고정된 상태, 장해는 치유되었으나 노동능력이 상실·감소된 상태, 중증요양상태는 치유되지 않은 채 노동능력이 상실·감소된 상태":"치유는 증상이 고정된 상태, 장해는 치유 후 노동능력이 줄어든 상태, 중증요양상태는 치유되지 않았는데 노동능력이 줄어든 상태입니다.","치유 후 상시·수시 간병이 필요해 실제로 간병을 받는 사람에게 지급하고 재요양 기간에는 주지 않음(제61조)":"간병급여는 치유 후 실제로 간병을 받는 사람에게 주고 재요양 기간에는 주지 않습니다.","치유 후 장해가 있으면 장해등급에 따라 연금 또는 일시금을 수급권자 선택으로 지급하되, 노동력을 완전히 상실한 등급은 연금, 청구 당시 외국에 사는 외국인은 일시금(제57조)":"장해급여는 장해등급에 따라 연금 또는 일시금으로 지급하며 선택은 수급권자가 하고 완전 상실 등급은 연금, 외국 거주 외국인은 일시금입니다.","타인의 사업을 위해 직접 노무를 제공하고 대가를 받는 사람으로 대통령령으로 정한 직종에 종사하는 사람(제91조의15)":"노무제공자는 타인의 사업을 위해 직접 노무를 제공하고 대가를 받는 사람으로 대통령령이 정한 직종에 종사해야 합니다.","탈퇴 후 계속 재직하면 다시 가입할 수 없으며 보험료는 소속기관과 본인이 2분의 1씩 부담":"탈퇴한 뒤 계속 재직 중이면 다시 가입할 수 없고 보험료는 소속기관과 본인이 절반씩 냅니다.","태아였던 자녀가 출생하면 그 다음 달분부터 금액을 조정":"태아였던 자녀가 태어나면 그 다음 달분부터 연금액을 다시 조정합니다.","판정위원회 심의를 거친 급여 결정에는 심사청구 없이 바로 재심사를 청구할 수 있음":"판정위원회 심의를 거친 급여 결정은 심사청구를 건너뛰고 바로 재심사를 청구할 수 있습니다.","평균임금 120일분이고 유족이 아닌 사람이 장례를 지내면 그 범위에서 실비를 지급(제71조)":"장례비는 평균임금 120일분이고 유족이 아닌 사람이 장례를 치르면 그 범위에서 실비를 줍니다.","평균임금이 최저임금액의 70분의 100보다 적으면 그 금액을 평균임금으로 보고(제67조), 61세부터 고령자 기준으로 감액하며(제68조), 재요양은 시작 후 2년이 지나야 함":"평균임금이 기준에 못 미치면 그 금액으로 보고 61세부터는 고령자 기준으로 감액하며 재요양은 시작 후 2년이 지나야 합니다.","폐업·도산으로 보수를 확인하기 어렵거나 사업장 이전으로 소재지를 파악하기 어려우면 고용노동부장관이 고시한 기준보수를 보수로 할 수 있음":"보수를 확인하기 어려운 경우에는 고용노동부장관이 고시한 기준보수를 보수로 삼을 수 있습니다.","피보험 단위기간은 보수 지급의 기초가 된 날을 합해 계산(제41조)":"피보험 단위기간은 달력상 기간이 아니라 보수 지급의 기초가 된 날을 더해 계산합니다.","피보험자격 확인, 실업급여, 육아휴직·출산전후휴가 급여 처분에 이의가 있으면 처분이 있음을 안 날부터 90일 이내에 고용보험심사관에게 심사를 청구(제87조) · 자격 확인은 근로복지공단을, 급여 처분은 직업안정기관의 장을 거쳐 청구하며(제90조), 그 기관은 5일 이내에 의견서를 붙여 보냄":"처분에 불복하면 안 날부터 90일 안에 고용보험심사관에게 심사를 청구하고 해당 기관을 거쳐 내며 그 기관은 5일 안에 의견서를 붙입니다.","피보험자나 피보험자였던 사람은 언제든지 취득·상실의 확인을 청구할 수 있음(제17조)":"피보험자 또는 과거 피보험자는 언제든 취득·상실 확인을 청구할 수 있습니다.","피보험자와 사업주 사이의 고용관계가 끝나는 것이고 새 사업주와의 계약은 요건이 아님":"이직은 사업주와의 고용관계가 끝나는 것이며 새 사업주와 계약할 필요는 없습니다.","피부양자는 사망·국적상실은 다음 날, 직장가입자가 자격을 잃으면 그날, 본인 신고로 상실하면 신고한 날의 다음 날 잃음":"피부양자 자격 상실 시점은 사유에 따라 다음 날이거나 그날이거나 신고 다음 날로 갈립니다.","회계연도 종료 후 2개월 이내에 실적과 결산을 보고하고, 보험급여 지급 업무는 체신관서에 위탁할 수 있음":"공단은 회계연도 종료 후 2개월 안에 실적과 결산을 보고하고 급여 지급은 체신관서에 맡길 수 있습니다.","효과·경제성이 불확실해 추가 근거가 필요하면 선별급여로 실시할 수 있음(제41조의4)":"효과나 경제성이 불확실해 추가 근거가 필요하면 선별급여로 실시할 수 있습니다.","훈련연장급여 중에는 개별·특별연장급여를 주지 않고, 개별·특별연장급여 중 훈련연장급여를 받게 되면 앞의 것은 중단하며 특별연장급여가 끝나야 개별연장급여를 줌":"연장급여는 중복해서 받을 수 없고 훈련연장급여를 우선하며 특별연장급여가 끝나야 개별연장급여를 줍니다.","휴직자등은 사유가 생기기 전 달의 보수월액으로 산정":"휴직하면 보수가 줄므로 보험료는 휴직 전 달의 보수월액으로 계속 계산합니다.","휴직 중 이직하면 그때부터 지급하지 않고, 부정수급 이후 새 요건을 갖추면 새 급여는 받으며 사업주와 공모한 부정수급은 형벌 대상":"휴직 중 이직하면 그때부터 지급이 끝나고 사업주와 공모한 부정수급은 형벌 대상이며 부정수급 후 새 요건을 갖추면 새 급여는 받습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
